var n=`0484-hummus`;var a=`world-0484`;var t=`LB`;var s=`western-asia`;var l=4;var r=596;var o={en:`Hummus`,ua:`Хумус`};var m={en:`A traditional dish from Lebanon, centered on chickpeas, tahini, lemon juice, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: нут, тахіні, лимонний сік, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var c=[{en:`Soak the dried chickpeas in plenty of cool water for at least 8 hours, preferably in the refrigerator, then drain.`,ua:`Замочіть сухий нут у великій кількості прохолодної води щонайменше на 8 годин, бажано в холодильнику, потім злийте воду.`,t:[`soaking-legumes`],m:480,i:[[`chickpeas`,260,`g`]]},{en:`Simmer soaked chickpeas in fresh water until extremely soft, about 90–105 minutes; drain, reserving some liquid.`,ua:`Відварюйте замочений нут у свіжій воді до повної м’якості приблизно 90–105 хвилин; відцідіть, трохи відвару збережіть.`,t:[`boiling`],m:105,i:[[`water`,1200,`ml`]]},{en:`Blend fully cooked chickpeas with tahini, lemon, garlic, salt and ice-cold water until exceptionally smooth and fluffy.`,ua:`Збийте повністю готовий нут із тахіні, лимонним соком, часником, сіллю й холодною водою до ніжної пухкої маси.`,t:[`mixing`],m:8,i:[[`tahini`,130,`g`],[`lemon-juice`,90,`ml`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,60,`ml`],[`water`,110,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`sweet-paprika`,3,`g`],[`parsley`,15,`g`]]}];var u={slug:n,id:a,country:`LB`,region:s,servings:4,minutes:596,title:o,text:m,steps:c};export{t as country,u as default,a as id,r as minutes,s as region,l as servings,n as slug,c as steps,m as text,o as title};